 ('20000000-0000-4000-8000-000000000001','vision-benefit','b','{"a":"This lists features. Look for the change in the learner’s experience.","b":"Yes. This expresses a future benefit, though a complete vision needs more context.","c":"This is a near-term metric, not the intended future experience."}',false),
 ('20000000-0000-4000-8000-000000000001','review-1','b','{"a":"A feature list does not describe the future benefit.","b":"Yes. This describes a meaningful change for a user.","c":"A signup target is a metric, not a vision."}',true),
 ('20000000-0000-4000-8000-000000000001','review-2','a','{"a":"Yes. A shared vision gives direction for trade-offs.","b":"Feature counts alone do not show the desired future.","c":"A vision should guide learning about users, not replace it."}',true) on conflict do nothing;
